INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(18600, 'koKR', 'Słychać głośny zgrzyt metalu trącego o kamień...', '', 0),
(20705, 'koKR', 'Tak jest!', '', 0),
(20706, 'koKR', 'Spocznij, żołnierze!', '', 0),
(20711, 'koKR', 'Broń w gotowości!', '', 0),
(20712, 'koKR', 'Atak pierwszy!', '', 0),
(20713, 'koKR', 'Atak drugi!', '', 0),
(20714, 'koKR', 'Atak trzeci!', '', 0),
(20716, 'koKR', 'Hop!', '', 0),
(20717, 'koKR', 'Hura!', '', 0),
(20718, 'koKR', 'Aaaaaaaaaaaaaaaaaaaa!', '', 0),
(20814, 'koKR', 'Przeszukajcie okolicę i meldujcie o wszystkim, co zobaczycie!', 'Przeszukajcie okolicę i meldujcie o wszystkim, co zobaczycie!', 0),
(20823, 'koKR', 'Smoczy jeźdźcy, na grzbiety!', 'Smoczy jeźdźcy, na grzbiety!', 0),
(20826, 'koKR', 'Proszę o zgodę na niski przelot nad wieżą!', 'Proszę o zgodę na niski przelot nad wieżą!', 0),
(20856, 'koKR', 'Przygotować się do wymarszu!', '', 0),
(20857, 'koKR', 'Doskonale!', '', 0),
(20893, 'koKR', 'Przyszliśmy położyć kres twoim rządom, Illidanie. Mój lud i cała Rubież będą wolne!', '', 0),
(20894, 'koKR', 'Nadszedł czas! Ta chwila jest już bliska!', '', 0),
(20902, 'koKR', 'Bądźcie czujni, przyjaciele. Zdrajca medytuje na dziedzińcu tuż za nami.', '', 0),
(20903, 'koKR', 'Jesteśmy gotowi stawić czoła Illidanowi.', 'Jesteśmy gotowi stawić czoła Illidanowi.', 0),
(21018, 'koKR', 'Ziemia zaczyna pękać!', '', 0),
(21019, 'koKR', 'Supremus w gniewie uderza pięścią w ziemię!', '', 0),
(21078, 'koKR', 'Illidan mocno trzyma moje plemię w garści, $n. Wkrótce wszystko się skończy, tak czy inaczej.$B$BJesteś $ggotów:gotowa;, $n? Przyszłość mojego ludu zależy od nas.', '', 0),
(21085, 'koKR', 'Zginiesz w imię Lady Vash!', '', 0),
(21087, 'koKR', 'Krew... się... poleje!', '', 0),
(21088, 'koKR', 'Be\'lanen dalorai!', '', 0),
(21089, 'koKR', 'Zostań na dłużej...', '', 0),
(21090, 'koKR', 'Tobą zajmę się później.', '', 0),
(21091, 'koKR', 'Twój sukces nie trwał długo!', '', 0),
(21092, 'koKR', 'Pora na ciebie.', '', 0),
(21093, 'koKR', 'Lord Illidan... zmiażdży was!', '', 0),
(21095, 'koKR', 'Bal, lamer zhita!', '', 0),
(21096, 'koKR', 'Skończyła mi się cierpliwość! Giń! Giń!', '', 0),
(21097, 'koKR', 'Pomsta należy do mnie!', '', 0),
(21098, 'koKR', 'Byłem pierwszy, wiesz? Dla mnie koło śmierci obróciło się już wiele razy. Minęło tyle czasu... Mam sporo do nadrobienia.', '', 0),
(21099, 'koKR', 'Przydasz mi się...', '', 0),
(21100, 'koKR', 'Będzie gorzej.', '', 0),
(21101, 'koKR', 'Śmierć naprawdę nie jest taka zła.', '', 0),
(21102, 'koKR', 'Czego się boisz?', '', 0),
(21103, 'koKR', 'Poddaj się.', '', 0),
(21104, 'koKR', 'Mam coś dla ciebie...', '', 0),
(21105, 'koKR', 'Okażesz należny szacunek!', '', 0),
(21106, 'koKR', 'Koło... znów... się obraca.', '', 0),
(21250, 'koKR', 'Ja zajmę się tymi kundlami! Uderzajcie teraz, przyjaciele! Uderzcie na Zdrajcę!', '', 0),
(21253, 'koKR', 'Poddaję się! Tym razem wygrana twoja...', '', 0),
(21254, 'koKR', 'Dobra walka!', '', 0),
(21255, 'koKR', 'Widzieliście ten ostatni cios? Niesamowite!', '', 0),
(21256, 'koKR', 'Zabij go!', '', 0),
(21257, 'koKR', 'Słabeusz!', '', 0),
(21258, 'koKR', 'Wykończ go!', '', 0),
(21267, 'koKR', 'Jak długo mamy czekać?', '', 0),
(21268, 'koKR', 'Pewnego dnia to my będziemy władać tą mroczną świątynią.', '', 0),
(21269, 'koKR', 'Muszę się nażreć!', '', 0),
(21342, 'koKR', 'Złamani z plemienia Popielnych Języków, przemawia do was wasz przywódca!', '', 0),
(21343, 'koKR', 'Zdrajca nie ma już nad nami władzy. Jego mroczna magia, która spętała dusze Popielnych Języków, została zniszczona!', '', 0),
(21344, 'koKR', 'Wyjdźcie z cienia! Wróciłem, by poprowadzić was przeciw naszemu prawdziwemu wrogowi! Zrzućcie kajdany i podnieście broń przeciw swoim panom z Illidari!', '', 0),
(21352, 'koKR', '%s wpada w coraz większy szał, widząc, jak padają jego sojusznicy!', '%s wpada w coraz większy szał, widząc, jak padają jego sojusznicy!', 0),
(21353, 'koKR', 'Przestańcie się obijać i walczcie jak prawdziwe spaczone orki!', 'Przestańcie się obijać i walczcie jak prawdziwe spaczone orki!', 0),
(21354, 'koKR', 'Widziałem gnomki, które biją mocniej od was!', 'Widziałem gnomki, które biją mocniej od was!', 0),
(21355, 'koKR', 'To ma być natarcie? Widziałem biegusy, które nacierały z większym zapałem!', 'To ma być natarcie? Widziałem biegusy, które nacierały z większym zapałem!', 0),
(21356, 'koKR', 'Jak nie zaczniecie porządnie przywalać, przez rok będziecie sprzątać boksy smokowców!', 'Jak nie zaczniecie porządnie przywalać, przez rok będziecie sprzątać boksy smokowców!', 0),
(21357, 'koKR', '', 'Przestańcie igrać z moimi uczuciami!', 0),
(21441, 'koKR', 'Postawa bojowa! Szykujcie się do natarcia!', '', 0),
(21443, 'koKR', 'Postawa berserkera! Atakujcie bez opamiętania!', '', 0),
(21444, 'koKR', 'Postawa defensywna! Osłońcie się przed ich ciosami i kontratakujcie!', '', 0),
(21494, 'koKR', 'Drzwi do Nory Śmiertelnych Rozkoszy stanęły otworem.', '', 0),
(21514, 'koKR', 'Światłość znów pobłogosławi te ponure sale... Przysięgam.', '', 0),
(21518, 'koKR', 'Wszyscy, którzy zbezcześcili tę świątynię, zostali pokonani. Wszyscy oprócz jednego!', '', 0),
(21520, 'koKR', 'Dokończmy to, co zaczęliśmy. Gdy odzyskacie siły, zaprowadzę was do siedziby Illidana.', '', 0),
(21521, 'koKR', 'Nadszedł czas, by stawić czoła Illidanowi, $n. Jesteś $ggotów:gotowa;?', '', 0),
(21522, 'koKR', 'Jestem $ggotów:gotowa;, Akamo.', 'Jestem $ggotów:gotowa;, Akamo.', 0),
(21545, 'koKR', 'Nie jesteś sam, Akamo.', '', 0),
(21546, 'koKR', 'Twój lud zawsze będzie z tobą!', '', 0),
(21548, 'koKR', 'Nie zdołam zrobić tego sam...', '', 0),
(21554, 'koKR', 'Dziękuję wam za pomoc, bracia. Nasz lud zostanie odkupiony!', '', 0),
(21555, 'koKR', 'Bądźcie czujni, przyjaciele. Zdrajca medytuje na dziedzińcu tuż za nami.', '', 0),
(21563, 'koKR', 'Tylko te drzwi dzielą nas od Zdrajcy. Odsuńcie się, przyjaciele.', '', 0),
(21698, 'koKR', 'Chcesz mnie sprawdzić?', '', 0),
(21699, 'koKR', 'Dzielna próba.', '', 0),
(21701, 'koKR', 'Wspaniałe zabójstwo!', '', 0),
(21703, 'koKR', 'Dopisało ci... szczęście.', '', 0),
(21704, 'koKR', 'Nie nadajesz się do tego.', '', 0),
(21705, 'koKR', 'Anar\'alah belore!', '', 0),
(21707, 'koKR', 'Chcesz mnie zabić? Ty zginiesz pierwszy!', '', 0),
(21711, 'koKR', '', 'Uciekaj albo giń!', 0),
(21712, 'koKR', '', 'Moja praca skończona.', 0),
(21713, 'koKR', '', 'Tak jak być powinno.', 0),
(21715, 'koKR', '', 'Przeznaczenie... czeka.', 0),
(21716, 'koKR', '', 'Nie ma drugiej szansy!', 0),
(21717, 'koKR', '', 'Za Quel\'Thalas! Za Słoneczną Studnię!', 0),
(21719, 'koKR', '', 'Jestem pełna niespodzianek!', 0),
(21724, 'koKR', 'Wspólny... cóż za prostacki język. Bandal!', '', 0),
(21725, 'koKR', 'Shorel\'aran.', '', 0),
(21727, 'koKR', 'Belesa menoor!', '', 0),
(21729, 'koKR', 'Diel ma\'ahn... orindel\'o.', '', 0),
(21730, 'koKR', 'Diel fin\'al.', '', 0),
(21731, 'koKR', 'Sha\'amoor ara mashal?', '', 0),
(21732, 'koKR', 'Shal\'mor sinabanal!', '', 0),
(21734, 'koKR', 'Mam ciekawsze rzeczy do roboty...', '', 0),
(21735, 'koKR', 'Selama am\'oronor!', '', 0),
(21737, 'koKR', 'Lordzie Illidanie, ja...', '', 0),
(21738, 'koKR', 'Nacieszcie się ostatnimi chwilami.', '', 0),
(21739, 'koKR', 'Należysz do mnie!', '', 0),
(21740, 'koKR', 'Horda... zmiażdży was.', '', 0),
(21741, 'koKR', 'Czas na ucztę.', '', 0),
(21742, 'koKR', 'Więcej! Chcę więcej!', '', 0),
